mapper.update:
UPDATE agent_version
SET connection_id = #{connectionId},
    model_profile_id = #{modelProfileId},
    prompt_version_id = #{promptVersionId},
    configuration_json = #{configurationJson},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND agent_definition_id = #{agentDefinitionId}
  AND status = 'DRAFT'

UPDATE agent_version
SET status = 'PUBLISHED',
    published_at = #{now},
    updated_at = #{now}
WHERE id = #{versionId}
  AND agent_definition_id = #{agentDefinitionId}
  AND status = 'DRAFT'

UPDATE agent_version
SET status = 'DISABLED',
    updated_at = #{now}
WHERE agent_definition_id = #{agentDefinitionId}
  AND status = 'DRAFT'

UPDATE agent_version
SET status = 'DISABLED',
    updated_at = #{now}
WHERE agent_definition_id = #{agentDefinitionId}
  AND status = 'DRAFT'

mapper.select:
SELECT COALESCE(MAX(version_number), 0) + 1
FROM agent_version
